def transform_ins_ins(a, b):   # transform a against already-applied b
    if b.pos < a.pos or (b.pos == a.pos and b.site < a.site):
        return Insert(a.pos + len(b.text), a.text, a.site)
    return a
def server_receive(op, base_rev):
    for applied in history[base_rev:]:
        op = transform(op, applied)
    history.append(op); broadcast(op, rev=len(history))

def diff(doc, remote_sv):
    missing = []
    for client, items in doc.items_by_client():
        have = remote_sv.get(client, 0)
        missing += [it for it in items if it.clock > have]
    return encode(missing, doc.delete_set())
# client: send sv -> recv diff(server, sv); send diff(client, server_sv)

def append(doc_id, token, ops):
    cur = meta.get_token(doc_id)
    if token < cur: raise StaleOwner()
    if token > cur: meta.set_token_if(doc_id, expected=cur, new=token)  # CAS
    seq = meta.next_seq(doc_id, len(ops))
    log.write_quorum(doc_id, seq, ops); return seq
